function frNum(n,f){
  const U=["zéro","un","deux","trois","quatre","cinq","six","sept","huit","neuf","dix","onze","douze","treize","quatorze","quinze","seize"];
  const T=["","","vingt","trente","quarante","cinquante","soixante"];
  let w;
  if(n<=16)w=U[n];
  else if(n<20)w="dix-"+U[n-10];
  else{
    const t=Math.floor(n/10),u=n%10;
    if(t<=6)w=T[t]+(u===0?"":(u===1?" et un":"-"+U[u]));
    else if(t===7){const m=n-60;w=m===11?"soixante et onze":"soixante-"+(m<17?U[m]:"dix-"+U[m-10])}
    else if(t===8)w=u===0?"quatre-vingts":"quatre-vingt-"+U[u];
    else{const m=n-80;w="quatre-vingt-"+(m<17?U[m]:"dix-"+U[m-10])}
  }
  return f?w.replace(/un$/,"une"):w;
}
