const vow=/^[aeiouéhê]/;
function gen(st){
  const s=SUB[st.s],parts=[[s[0],s[1],"S"]];let fr;
  if(st.m===2){
    const it=ITM[st.i],n=st.n,cj=VRB[2].c[s[3]];
    const nz=numZh(n,it);
    parts.push(["有","yǒu","V"],[nz[0],nz[1],"NUM"],[it.c,it.cp,"CL"],[it.h,it.p,"N"]);
    const q=n===1?it.f1:frNum(n,it.g==="f")+" "+it.fp;
    fr=(s[2]==="je"&&vow.test(cj))?"j'"+cj+" "+q:s[2]+" "+cj+" "+q;
    return {parts,fr:cap(fr),hz:parts.map(p=>p[0]).join("")+"。"};
  }
  if(st.m===1){
    const a=ADJ[st.a],vb=a[3]?a[3][st.s]:ETRE[st.s],g=s[2]==="elle"?1:(s[2]==="nous"?2:0),af=a[2][g];
    if(st.neg){parts.push(["不","bù","NEG"]);fr=s[2]+(vow.test(vb)?" n'":" ne ")+vb+" pas "+af}
    else{parts.push(["很","hěn","DEG"]);fr=s[2]+" "+vb+" très "+af}
    parts.push([a[0],a[1],"ADJ"]);
  }else{
    const v=VRB[st.v];let o=v.o[st.o];const cj=v.c[s[3]];
    if(st.neg){
      if(v.h==="有")parts.push(["没","méi","NEG"],["有","yǒu","V"]);else parts.push(["不","bù","NEG"],[v.h,v.p,"V"]);
      if(v.h!=="喜欢"&&NEGO[o[0]])o=NEGO[o[0]];
      fr=s[2]+(vow.test(cj)?" n'":" ne ")+cj+" pas "+o[2];
    }else{
      parts.push([v.h,v.p,"V"]);
      fr=(s[2]==="je"&&vow.test(cj))?"j'"+cj+" "+o[2]:s[2]+" "+cj+" "+o[2];
    }
    parts.push([o[0],o[1],"O"]);
  }
  return {parts,fr:cap(fr),hz:parts.map(p=>p[0]).join("")+"。"};
}
